package com.hostelmanagement.ai;
import com.hostelmanagement.entity.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class ComplaintAnalysisService { public Map<String,String> analyze(String text){String t=text.toLowerCase(); String cat=t.contains("water")||t.contains("pipe")?"Plumbing":t.contains("internet")||t.contains("wifi")?"Internet":t.contains("food")||t.contains("mess")?"Food":t.contains("light")||t.contains("electric")?"Electrical":t.contains("clean")?"Cleaning":"Other"; String priority=(t.contains("continuously")||t.contains("danger")||t.contains("fire"))?"HIGH": "MEDIUM"; String sentiment=(t.contains("bad")||t.contains("angry")||t.contains("urgent"))?"NEGATIVE":"NEUTRAL"; String dept=cat.equals("Food")?"Mess":cat.equals("Other")?"Hostel Administration":"Maintenance"; String action=cat.equals("Plumbing")?"Inspect and repair the affected pipe":cat.equals("Internet")?"Check network connectivity and access point":"Review complaint and assign responsible staff"; return Map.of("category",cat,"priority",priority,"sentiment",sentiment,"summary",text.length()>80?text.substring(0,80)+"...":text,"department",dept,"suggestedAction",action); } }
